const create = useForm({ title: '', slug: '', event_type: 'webinar', summary: '', description: '', cover_image: '', cover_upload: null, starts_at: '', timezone: 'Asia/Kolkata', duration_minutes: 60, host_name: '', host_title: '', meeting_url: '', replay_url: '', capacity: '', price: '0.00', currency: 'INR', status: 'draft' });
</script>

<template><StaffAdminLayout><div class="admin-heading"><div><div class="eyebrow">COMMUNITY PROGRAMMING</div><h1>Webinars & events.</h1><p>Host useful conversations, build your community, and give people a clear way to join live.</p></div><Link :href="wayfinderIndex1().url" target="_blank" class="admin-secondary">View public events <UiIcon name="arrow-up-right" :size="13"/></Link></div>
