dian rupee</option><option value="USD">USD · US dollar</option><option value="EUR">EUR · Euro</option><option value="GBP">GBP · Pound sterling</option></select></label></div><label>Event details<textarea v-model="create.description" required minlength="20" rows="6"></textarea></label><div class="admin-form-grid"><label>Event cover image<input type="file" accept="image/jpeg,image/png,image/webp" @input="create.cover_upload = $event.target.files[0] || null"><small>JPG, PNG, or WebP · up to 5 MB.</small><small class="admin-form-error">{{ create.errors.cover_upload }}</small></label><label>Live room URL <small>(shown only after registration)</small><input v-model="create.meeting_url" type="url" placeholder="https://..."></label></div><div class="admin-form-grid"><label>Replay URL <small>(shown after the event)</small><input v-model="create.replay_url" type="url" placeholder="https://..."></label><label>Publishing status<select v-model="create.status"><option value="draft">Draft</option><option value="published">Publish now</option></select></label></div><div class="admin-form-actions"><button class="button button-dark" :disabled="create.processing">Create event <UiIcon name="arrow-up-right" :size="13"/></button></div></form></section>
